<?php declare(strict_types=1);require_once dirname(__DIR__).'/_bootstrap.php';apiMethod('POST');apiCsrf();$uid=apiAuth();$in=apiInput();$db=apiDb();try{$db->beginTransaction();$s=$db->prepare('SELECT id FROM carts WHERE user_id=? AND status="active" FOR UPDATE');$s->execute([$uid]);$cart=$s->fetch();if(!$cart)apiError('Cart is empty',422);$s=$db->prepare('SELECT ci.product_id,ci.quantity,ci.unit_price FROM cart_items ci JOIN products p ON p.id=ci.product_id WHERE ci.cart_id=? AND p.status="active"');$s->execute([$cart['id']]);$items=$s->fetchAll();if(!$items)apiError('Cart is empty',422);$total=0;foreach($items as $i)$total+=(float)$i['unit_price']*(int)$i['quantity'];$number='QS-'.date('YmdHis').'-'.random_int(100,999);$s=$db->prepare('INSERT INTO orders(user_id,order_number,subtotal,total_amount,payment_method,order_status,shipping_address) VALUES(?,?,?,?,?,"Pending",?)');$s->execute([$uid,$number,$total,$total,(string)($in['payment_method']??'OTHER'),trim((string)($in['shipping_address']??''))]);$oid=(int)$db->lastInsertId();$s=$db->prepare('INSERT INTO order_items(order_id,product_id,quantity,unit_price,subtotal) VALUES(?,?,?,?,?)');foreach($items as $i)$s->execute([$oid,$i['product_id'],$i['quantity'],$i['unit_price'],(float)$i['unit_price']*(int)$i['quantity']]);$db->prepare('DELETE FROM cart_items WHERE cart_id=?')->execute([$cart['id']]);$db->prepare('UPDATE carts SET status="converted" WHERE id=?')->execute([$cart['id']]);$db->commit();apiResponse(['id'=>$oid,'total_amount'=>$total],201);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();apiException($e);}